import sys
from collections import defaultdict
import heapq

MOD = 10**9 + 7

def read_ints():
    return list(map(int, sys.stdin.readline().strip().split()))

def add_edge(graph, u, v, capacity):
    graph[u].append((v, capacity))
    graph[v].append((u, capacity))

def min_cut(graph, source, sink):
    n = len(graph)
    visited = [False] * n
    queue = [source]
    visited[source] = True
    while queue:
        u = queue.pop(0)
        for v, capacity in graph[u]:
            if not visited[v] and capacity > 0:
                visited[v] = True
                queue.append(v)
    return visited[sink]

def solve(N, M, edges):
    graph = defaultdict(list)
    for u, v, w in edges:
        add_edge(graph, u - 1, v - 1, w)

    result = 1
    for i in range(N):
        for j in range(i + 1, N):
            if min_cut(graph, i, j):
                result = (result * min_cut(graph, i, j)) % MOD
    return result

# Read input
N, M = read_ints()
edges = [read_ints() for _ in range(M)]

# Solve the problem
answer = solve(N, M, edges)

# Output the result
print(answer)
